# ----------------------------------------------------------------------
# Incremental merge helpers
# ----------------------------------------------------------------------

def append_to_merged(tmpfile, merged_file):
    """
    Append one temporary CSV into the cumulative merged CSV.
    Keep the header only once.
    """

    if not os.path.exists(tmpfile):
        return

    merged_exists = os.path.exists(merged_file)

    with open(tmpfile, "r") as fin:
        lines = fin.readlines()

    if not lines:
        return

    # Skip header if merged file already exists
    if merged_exists:
        lines = lines[1:]

    with open(merged_file, "a") as fout:
        fout.writelines(lines)

    # Remove temporary file immediately
    try:
        os.remove(tmpfile)
    except OSError as e:
        print(f"Could not delete {tmpfile}: {e}")


# ----------------------------------------------------------------------
# Functions
# ----------------------------------------------------------------------

def run_brilcalc(hltpath, tag, run):

    outfile = f"{tag}_{run}.csv"
    merged_file = f"{tag}_merged.csv"

    bril_command = f"""
    source {BRIL_ENV}

    brilcalc trg \
        --hltpath '{hltpath}' \
        --prescale \
        --output-style=csv \
        -o {outfile} \
        -r {run}
    """

    print(f"Running run={run} trigger={tag}")

    try:
        subprocess.run(
            [
                "bash",
                "-i",
                "-c",
                bril_command
            ],
            check=True,
        )

        append_to_merged(outfile, merged_file)

    except subprocess.CalledProcessError as e:
        print(f"ERROR for run {run}, trigger {tag}")
        print(e)
        
    
# ----------------------------------------------------------------------
# Main
# ----------------------------------------------------------------------

def main():

    total_runs = len(ALL_2018_RUNS)

    for idx, run in enumerate(ALL_2018_RUNS, start=1):

        if run < 321051: continue

        print(f"\n===== RUN {run} ({idx}/{total_runs}) =====")

        for hltpath, tag in TRIGGERS:
            run_brilcalc(hltpath, tag, run)

    print("\nDone.")
    

if __name__ == "__main__":
    main()